<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../core/SmsGatewayService.php';
Auth::requirePermission('sms_delivery_sync','edit');$pageTitle='همگام‌سازی تحویل پیامک';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('درخواست نامعتبر است.','danger');redirect('/admin/sms-delivery-sync.php');}$id=max(0,(int)($_POST['id']??0));$message=Database::fetch('SELECT id,bulk_code FROM sms_messages WHERE id=? AND bulk_code IS NOT NULL',[$id]);if(!$message){flash('گزارش ارسال معتبر نیست.','danger');redirect('/admin/sms-delivery-sync.php');}try{$result=SmsGatewayService::active()->getStatus((string)$message['bulk_code']);$text=$result['message']." تحویل‌شده: {$result['delivered']}، ناموفق: {$result['failed']}، نامشخص: {$result['unknown']}";flash($text,$result['success']?'success':'danger');Auth::log((int)Auth::user()['id'],'sms_delivery_sync','sms_messages',$id);}catch(Throwable $e){error_log('SMS delivery page: '.get_class($e));flash('همگام‌سازی وضعیت تحویل انجام نشد.','danger');}redirect('/admin/sms-delivery-sync.php');}
$rows=Database::fetchAll("SELECT id,created_at,sender,bulk_code,status,recipients_count,last_checked_at FROM sms_messages WHERE bulk_code IS NOT NULL AND status IN ('sent','partially_sent','unknown','checking_delivery','partially_delivered') ORDER BY id DESC LIMIT 200");require __DIR__.'/../views/partials/admin-header.php';?>
<section class="card"><h2>ارسال‌های قابل بررسی</h2><p class="muted">وضعیت‌های ناشناخته سرویس‌دهنده بدون حذف یا تبدیل اجباری ذخیره می‌شوند.</p><div class="table-wrap"><table><thead><tr><th>تاریخ</th><th>فرستنده</th><th>کد</th><th>گیرندگان</th><th>وضعیت</th><th>آخرین بررسی</th><th>عملیات</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['created_at'])?></td><td dir="ltr"><?=e($row['sender'])?></td><td dir="ltr"><?=e($row['bulk_code'])?></td><td><?=e((string)$row['recipients_count'])?></td><td><?=e($row['status'])?></td><td><?=e($row['last_checked_at']?:'-')?></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=$row['id']?>"><button class="btn btn-small">بروزرسانی وضعیت تحویل</button></form></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="7">پیامکی برای همگام‌سازی وجود ندارد.</td></tr><?php endif?></tbody></table></div></section>
<?php require __DIR__.'/../views/partials/admin-footer.php';
